// src/lib/toast.ts: PrimeVue's useToast().add() over vue-sonner, so every caller keeps its behaviour and changes only its import.
// New code calls toast() from vue-sonner. Remove this file once the callers have moved.
import { toast } from 'vue-sonner'

export interface ToastMessageOptions {
  severity?: 'success' | 'info' | 'warn' | 'error' | 'secondary' | 'contrast'
  summary?: string
  detail?: string
  /** Milliseconds; without it the notice stays until it is closed, as in PrimeVue. */
  life?: number
  closable?: boolean
  /** Set by add, so remove can take back the same object. */
  id?: string | number
  group?: string
}

const bySeverity = { success: toast.success, info: toast.info, warn: toast.warning, error: toast.error }

export function useToast() {
  return {
    add(message: ToastMessageOptions): void {
      const show = message.severity && message.severity in bySeverity ? bySeverity[message.severity as keyof typeof bySeverity] : toast
      message.id = show(message.summary ?? '', {
        description: message.detail,
        duration: message.life ?? Number.POSITIVE_INFINITY,
        dismissible: message.closable !== false,
        closeButton: message.closable !== false,
      })
    },
    remove(message: ToastMessageOptions): void {
      if (message.id !== undefined) toast.dismiss(message.id)
    },
    removeAllGroups(): void {
      toast.dismiss()
    },
  }
}

// src/lib/confirm.ts: PrimeVue's useConfirm().require() over the confirm-host block, so every caller keeps its behaviour and
// changes only its import. Mount <ConfirmHost /> once in App (and <ConfirmHost group="…" /> where a page had its own group).
// New code calls useConfirm().ask() from @/components/blocks/confirm. Remove this file once the callers have moved.
import { useConfirm as useConfirmHost } from '@/components/blocks/confirm'

export interface ConfirmationOptions {
  header?: string
  message?: string
  acceptLabel?: string
  rejectLabel?: string
  acceptProps?: { label?: string, severity?: string }
  rejectProps?: { label?: string }
  acceptClass?: string
  accept?: () => unknown
  reject?: () => unknown
  onHide?: () => unknown
  group?: string
  /** Set by ConfirmPopup callers: the anchored popup becomes the same dialog, shown by the host in App. */
  target?: unknown
}

export function useConfirm() {
  const host = useConfirmHost()
  return {
    require(options: ConfirmationOptions): void {
      const danger = options.acceptProps?.severity === 'danger' || /danger/.test(options.acceptClass ?? '')
      host.ask({
        title: options.header ?? options.message ?? '',
        message: options.header ? options.message : undefined,
        confirmLabel: options.acceptProps?.label ?? options.acceptLabel,
        cancelLabel: options.rejectProps?.label ?? options.rejectLabel,
        variant: danger ? 'destructive' : 'default',
        group: options.target ? undefined : options.group,
        action: async () => {
          const result = await options.accept?.()
          options.onHide?.()
          return result
        },
        onCancel: () => {
          options.reject?.()
          options.onHide?.()
        },
      })
    },
    close: host.close,
  }
}
